// Circuit outlines for covers (?circuit=<slug>). The data in data/circuits.json
// is generated by scripts/build-circuits.mjs — see data/CIRCUITS-LICENSE.md.

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { OUTLINE } from "./config.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Literal path on purpose (same reason as lib/fonts.mjs): Vercel's file tracer
// follows static fs.readFileSync calls.
const CIRCUITS = JSON.parse(fs.readFileSync(path.join(__dirname, "../data/circuits.json"), "utf8"));

export const circuitSlugs = Object.keys(CIRCUITS);

// hasOwn, not `slug in CIRCUITS`: slugs come from the URL, and "constructor" or
// "__proto__" must not resolve to something on Object.prototype.
export function getCircuit(slug) {
  return typeof slug === "string" && Object.hasOwn(CIRCUITS, slug) ? CIRCUITS[slug] : null;
}

// The outline as an SVG data URI, stroked in `color` (a validated #rrggbb),
// ready to hand to the template as an <img> source. Returns null for an
// unknown slug.
export function circuitOutlineDataUri(slug, color) {
  const circuit = getCircuit(slug);
  if (!circuit) return null;

  const stroke = Math.round(1000 * OUTLINE.strokeShare);
  const w = circuit.width + 2 * stroke;
  const h = circuit.height + 2 * stroke;
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="${-stroke} ${-stroke} ${w} ${h}">` +
    `<path d="${circuit.path}" fill="none" stroke="${color}" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round"/>` +
    `</svg>`;
  return `data:image/svg+xml;base64,${Buffer.from(svg).toString("base64")}`;
}
